73	/// Service controller interface for managing the netclient lifecycle.
74	#[derive(Clone)]
75	enum ServiceController {
76	    /// s6 via org.opdbus.v1.S6.Systemctl
77	    S6 { connection: Connection },
78	}
79	
80	impl ServiceController {
81	    /// Detect the appropriate service controller for this system
82	    async fn detect() -> Result<Self> {
83	        if !Path::new("/run/s6-rc").exists() && !Path::new("/run/service").exists() {
84	            return Err(anyhow::anyhow!(
85	                "s6 runtime not found; netclient is managed through org.opdbus.v1.S6.Systemctl"
86	            ));
87	        }
88	
89	        let conn = Connection::system()
90	            .await
91	            .context("Failed to connect to system D-Bus for s6")?;
92	        Proxy::new(
93	            &conn,
94	            "org.opdbus.v1.S6.Systemctl",
95	            "/org/opdbus/v1/plugins/s6/systemctl",
96	            "org.opdbus.v1.S6.Systemctl",
97	        )
98	        .await
99	        .context("s6-systemctl D-Bus service is unavailable")?;
100	
101	        Ok(ServiceController::S6 { connection: conn })
102	    }
103	
104	    /// Check if a service is active
105	    async fn is_active(&self, service: &str) -> Result<bool> {
106	        match self {
107	            ServiceController::S6 { connection } => {
108	                let proxy = Proxy::new(
109	                    connection,
110	                    "org.opdbus.v1.S6.Systemctl",
111	                    "/org/opdbus/v1/plugins/s6/systemctl",
112	                    "org.opdbus.v1.S6.Systemctl",
113	                )
114	                .await?;
115	
116	                let result: String = proxy.call("is_active", &(service,)).await?;
117	                Ok(result == "active")
118	            }
119	        }
120	    }
121	
122	    /// Enable and start a service (enable --now)
123	    async fn enable_and_start(&self, service: &str) -> Result<()> {
124	        match self {
125	            ServiceController::S6 { connection } => {
126	                let proxy = Proxy::new(
127	                    connection,
128	                    "org.opdbus.v1.S6.Systemctl",
129	                    "/org/opdbus/v1/plugins/s6/systemctl",
130	                    "org.opdbus.v1.S6.Systemctl",
131	                )
132	                .await?;
133	
134	                // Enable the service
135	                let (success, msg): (bool, String) = proxy.call("enable", &(service,)).await?;
136	
137	                if !success {
138	                    return Err(anyhow::anyhow!("Failed to enable {}: {}", service, msg));
139	                }
140	
141	                // Start the service
142	                let (success, msg): (bool, String) = proxy.call("start", &(service,)).await?;
143	
144	                if !success {
145	                    return Err(anyhow::anyhow!("Failed to start {}: {}", service, msg));
146	                }
147	
148	                Ok(())
149	            }
150	        }
151	    }
152	}
153	
154	pub struct NetmakerPlugin {
155	    config: NetmakerConfig,
156	}
157	
158	impl NetmakerPlugin {
159	    pub fn new(config: NetmakerConfig) -> Self {
160	        Self { config }
161	    }
162	
163	    /// Check if netclient is installed via direct file check (AGENTS.md §4: no subprocess bypasses)
164	    async fn check_netclient_installed() -> Result<bool> {
165	        Ok(std::path::Path::new("/usr/bin/netclient").exists()
166	            || std::path::Path::new("/usr/local/bin/netclient").exists())
167	    }
168	
169	    /// Check if netclient daemon is running via D-Bus
170	    async fn check_daemon_running() -> Result<bool> {
171	        let controller = ServiceController::detect().await?;
172	        controller.is_active("netclient").await
173	    }
174	
175	    fn netclient_config_path() -> &'static str {
176	        "/etc/netclient/netclient.json"
177	    }
178	
179	    async fn read_netclient_config() -> Result<JsonValue> {
180	        match tokio::fs::read_to_string(Self::netclient_config_path()).await {
181	            Ok(content) => Ok(serde_json::from_str(&content)
182	                .with_context(|| "Failed to parse /etc/netclient/netclient.json")?),
183	            Err(_) => Ok(serde_json::json!({})),
184	        }
185	    }
186	
187	    async fn write_netclient_config(mut config: JsonValue) -> Result<()> {
188	        if !config.is_object() {
189	            config = serde_json::json!({});
190	        }
191	
192	        tokio::fs::create_dir_all("/etc/netclient").await.ok();
193	        tokio::fs::write(
194	            Self::netclient_config_path(),
195	            serde_json::to_string_pretty(&config)?,
196	        )
197	        .await
198	        .context("Failed to write /etc/netclient/netclient.json")?;
199	        Ok(())
200	    }
201	
202	    async fn restart_netclient() -> Result<()> {
203	        let controller = ServiceController::detect().await?;
204	        controller.enable_and_start("netclient").await
205	    }
206	
207	    /// Get current networks from netclient config files (AGENTS.md §4: no subprocess bypasses)
208	    async fn get_networks(&self) -> Result<Vec<NetmakerNetwork>> {
209	        let mut networks = Vec::new();
210	
211	        // Read netclient.json to discover connected networks
212	        if let Ok(content) = tokio::fs::read_to_string("/etc/netclient/netclient.json").await {
213	            if let Ok(config) = simd_json::to_owned_value(&mut content.into_bytes()) {
214	                // Check nodes array for connected networks
215	                if let Some(nodes) = config.get("nodes").and_then(|n| n.as_array()) {
216	                    for node in nodes {
217	                        let network_name = node
218	                            .get("network")
219	                            .and_then(|v| v.as_str())
220	                            .unwrap_or("unknown")
221	                            .to_string();
222	                        let connected = node
223	                            .get("connected")
224	                            .and_then(|v| v.as_bool())
225	                            .unwrap_or(false);
226	                        let address = node
227	                            .get("address")
228	                            .and_then(|v| v.as_str())
229	                            .map(String::from);
230	
231	                        let peers = self
232	                            .get_network_peers(&network_name)
233	                            .await
234	                            .unwrap_or_default();
235	
236	                        networks.push(NetmakerNetwork {
237	                            name: network_name.clone(),
238	                            connected,
239	                            is_default: network_name == self.config.default_network,
240	                            node_id: node.get("id").and_then(|v| v.as_str()).map(String::from),
241	                            peers,
242	                            address,
243	                        });
244	                    }
245	                }
246	            }
247	        }
248	
249	        Ok(networks)
250	    }
251	
252	    /// Get peers for a specific network
253	    async fn get_network_peers(&self, network: &str) -> Result<Vec<String>> {
254	        // This is a simplified implementation
255	        // In reality, you'd need to query the Netmaker API or parse daemon state
256	        let _ = network; // Suppress unused variable warning
257	        Ok(Vec::new()) // TODO: Implement actual peer discovery
258	    }
259	
260	    /// Get public IP from netclient config (AGENTS.md §4: no subprocess bypasses)
261	    async fn get_public_ip(&self) -> Result<Option<String>> {
262	        if let Ok(content) = tokio::fs::read_to_string("/etc/netclient/netclient.json").await {
263	            if let Ok(config) = simd_json::to_owned_value(&mut content.into_bytes()) {
264	                return Ok(config
265	                    .get("endpointip")
266	                    .and_then(|v| v.as_str())
267	                    .map(String::from));
268	            }
269	        }
270	        Ok(None)
271	    }
272	
273	    /// Join a Netmaker network
274	    /// The control surface is the netclient config file plus the s6 restart path.
275	    async fn join_network(&self, network: &str, token: &str) -> Result<()> {
276	        let mut config = Self::read_netclient_config().await?;
277	        config["enabled"] = serde_json::json!(true);
278	        config["default_network"] = serde_json::json!(network);
279	        config["enrollment_token"] = serde_json::json!(token);
280	        config["interface"] = serde_json::json!("netmaker");
281	        config["inittype"] = serde_json::json!(6);
282	        Self::write_netclient_config(config).await?;
283	        Self::restart_netclient().await?;
284	        Ok(())
285	    }
286	
287	    /// Leave a Netmaker network
288	    async fn leave_network(&self, network: &str) -> Result<()> {
289	        let mut config = Self::read_netclient_config().await?;
