370	    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
371	        let mut actions = Vec::new();
372	
373	        // Check if netclient should be installed/enabled
374	        let current_installed = current
375	            .get("installed")
376	            .and_then(|v| v.as_bool())
377	            .unwrap_or(false);
378	        let desired_enabled = desired
379	            .get("config")
380	            .and_then(|c| c.get("enabled"))
381	            .and_then(|v| v.as_bool())
382	            .unwrap_or(false);
383	
384	        if !current_installed && desired_enabled {
385	            actions.push(StateAction::Create {
386	                resource: "netmaker_installation".to_string(),
387	                config: simd_json::json!({
388	                    "action": "install_netclient",
389	                    "type": "system_package"
390	                }),
391	            });
392	        }
393	
394	        // Check network membership changes
395	        let empty_networks = vec![];
396	        let current_networks = current
397	            .get("networks")
398	            .and_then(|n| n.as_array())
399	            .unwrap_or(&empty_networks);
400	        let desired_networks = desired
401	            .get("config")
402	            .and_then(|c| c.get("default_network"))
403	            .and_then(|n| n.as_str());
404	
405	        if let Some(desired_network) = desired_networks {
406	            let currently_connected = current_networks.iter().any(|net| {
407	                net.get("name").and_then(|n| n.as_str()) == Some(desired_network)
408	                    && net
409	                        .get("connected")
410	                        .and_then(|c| c.as_bool())
411	                        .unwrap_or(false)
412	            });
413	
414	            if !currently_connected && desired_enabled {
415	                actions.push(StateAction::Create {
416	                    resource: format!("netmaker_network_{}", desired_network),
417	                    config: simd_json::json!({
418	                        "network": desired_network,
419	                        "action": "join_network",
420	                        "type": "network_membership"
421	                    }),
422	                });
423	            }
424	        }
425	
426	        Ok(StateDiff {
427	            plugin: self.name().to_string(),
428	            actions,
429	            metadata: op_state::DiffMetadata {
430	                timestamp: std::time::SystemTime::now()
431	                    .duration_since(std::time::UNIX_EPOCH)?
432	                    .as_secs() as i64,
433	                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
434	                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
435	            },
436	        })
437	    }
