439	    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
440	        let mut changes_applied = Vec::new();
441	        let mut errors = Vec::new();
442	
443	        // Detect service controller once for all operations
444	        let controller = match ServiceController::detect().await {
445	            Ok(ctrl) => Some(ctrl),
446	            Err(e) => {
447	                errors.push(format!("Failed to detect service controller: {}", e));
448	                None
449	            }
450	        };
451	
452	        for action in &diff.actions {
453	            if let StateAction::Create {
454	                resource,
455	                config: _,
456	            } = action
457	            {
458	                if resource == "netmaker_installation" {
459	                    // Package installation requires PackageKit D-Bus or manual install per AGENTS.md §4
460	                    errors.push(
461	                        "Netclient package installation requires external PackageKit D-Bus or manual install (disabled per AGENTS.md §4). \
462	                         Run: apt-get install -y netclient".to_string(),
463	                    );
464	                    // Attempt to enable and start service via D-Bus regardless
465	                    if let Some(ref ctrl) = controller {
466	                        match ctrl.enable_and_start("netclient").await {
467	                            Ok(_) => {
468	                                changes_applied.push(
469	                                    "Enabled and started netclient service via D-Bus".to_string(),
470	                                );
471	                            }
472	                            Err(e) => {
473	                                errors.push(format!(
474	                                    "Failed to enable/start netclient via D-Bus: {}",
475	                                    e
476	                                ));
477	                            }
478	                        }
479	                    }
480	                } else if resource.starts_with("netmaker_network_") {
481	                    let network = resource.strip_prefix("netmaker_network_").unwrap_or("");
482	                    if let Some(token) = &self.config.enrollment_token {
483	                        match self.join_network(network, token).await {
484	                            Ok(_) => {
485	                                changes_applied.push(format!("Joined Netmaker network {}", network))
486	                            }
487	                            Err(e) => {
488	                                errors.push(format!("Failed to join network {}: {}", network, e))
489	                            }
490	                        }
491	                    } else {
492	                        errors.push(format!(
493	                            "No enrollment token configured for network {}",
494	                            network
495	                        ));
496	                    }
497	                }
498	            }
499	        }
500	
501	        Ok(ApplyResult {
502	            success: errors.is_empty(),
503	            changes_applied,
504	            errors,
505	            checkpoint: None,
