1	//! gRPC server — binds all adapters on a single unix socket with tonic-web,
2	//! reflection, health, and Ghostbridge interceptor.
3	
4	use anyhow::Result;
5	use tonic::transport::Server;
6	use tonic_health::server::health_reporter;
7	use tonic_reflection::server::Builder as ReflectionBuilder;
8	
9	use crate::adapters::{mail::MailAdapter, mq::MqAdapter, netmaker::NetmakerAdapter};
10	use crate::interceptor::ghostbridge_interceptor;
11	use crate::proto::{
12	    mail_service_server::MailServiceServer, mq_service_server::MqServiceServer,
13	    netmaker_service_server::NetmakerServiceServer, FILE_DESCRIPTOR_SET,
14	};
15	
16	pub async fn run(socket_path: &str) -> Result<()> {
17	    // Remove stale socket file
18	    let _ = std::fs::remove_file(socket_path);
19	
20	    let uds = tokio::net::UnixListener::bind(socket_path)?;
21	    let uds_stream = tokio_stream::wrappers::UnixListenerStream::new(uds);
22	
23	    let (mut health_reporter, health_service) = health_reporter();
24	    health_reporter
25	        .set_serving::<MailServiceServer<MailAdapter>>()
26	        .await;
27	    health_reporter
28	        .set_serving::<NetmakerServiceServer<NetmakerAdapter>>()
29	        .await;
30	    health_reporter
31	        .set_serving::<MqServiceServer<MqAdapter>>()
32	        .await;
33	
34	    let reflection = ReflectionBuilder::configure()
35	        .register_encoded_file_descriptor_set(FILE_DESCRIPTOR_SET)
36	        .build_v1()?;
37	
38	    tracing::info!(socket = socket_path, "op-grpc-adapters listening");
39	
40	    Server::builder()
41	        .accept_http1(true)
42	        .layer(tonic_web::GrpcWebLayer::new())
43	        .add_service(health_service)
44	        .add_service(reflection)
45	        .add_service(MailServiceServer::with_interceptor(
46	            MailAdapter::new(),
47	            ghostbridge_interceptor,
48	        ))
49	        .add_service(NetmakerServiceServer::with_interceptor(
50	            NetmakerAdapter::new(),
51	            ghostbridge_interceptor,
52	        ))
53	        .add_service(MqServiceServer::with_interceptor(
54	            MqAdapter::new(),
55	            ghostbridge_interceptor,
56	        ))
57	        .serve_with_incoming(uds_stream)
58	        .await?;
59	
60	    Ok(())
61	}
